{"implementation":"import math

def solve(case):
    matrix = case['matrix']
    if not matrix:
        return {"idf": [], "row_degree": [], "weighted_matrix": []}
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    idf = []
    for j in range(n_cols):
        df = sum(1 for i in range(n_rows) if matrix[i][j] != 0)
        idf_val = math.log(1 + n_rows / (1 + df))
        idf.append(idf_val)
    weighted_matrix = [[matrix[i][j] * idf[j] for j in range(n_cols)] for i in range(n_rows)]
    row_degree = [sum(weighted_matrix[i]) for i in range(n_rows)]
    return {"idf": idf, "row_degree": row_degree, "weighted_matrix": weighted_matrix}"}
